from collections import defaultdict, deque
from typing import Optional


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self.customers = {}  # name -> vip status
        self.ticket_counter = 0
        self.tickets = {}  # ticket_id -> ticket info dict
        # Queues: vip -> priority -> deque of ticket_ids
        self.queues = {
            True: {p: deque() for p in self.PRIORITIES},
            False: {p: deque() for p in self.PRIORITIES},
        }
        self.closed_tickets = set()

    def add_customer(self, name: str, vip: bool = False) -> None:
        self.customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")
        if customer not in self.customers:
            raise ValueError(f"Unknown customer: {customer}")

        self.ticket_counter += 1
        ticket_id = self.ticket_counter
        is_vip = self.customers[customer]
        self.tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "vip": is_vip,
            "status": "open",
        }
        self.queues[is_vip][priority].append(ticket_id)
        return ticket_id

    def next_ticket(self) -> Optional[int]:
        for vip in (True, False):
            for priority in reversed(self.PRIORITIES):
                queue = self.queues[vip][priority]
                if queue:
                    ticket_id = queue.popleft()
                    self.tickets[ticket_id]["status"] = "in_progress"
                    return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self.tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        self.tickets[ticket_id]["status"] = "closed"
        self.closed_tickets.add(ticket_id)

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self.tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        if ticket_id in self.closed_tickets:
            raise ValueError(f"Cannot reopen closed ticket id: {ticket_id}")
        ticket = self.tickets[ticket_id]
        if ticket["status"] == "open":
            return
        ticket["status"] = "open"
        self.queues[ticket["vip"]][ticket["priority"]].append(ticket_id)
```

